void RadixSort(DataType a[], int n, int m, int d)
/* 对数据元素 a[0]--a[n-1] 进行关键字为 m 位 d 进制整型数值的基
数排序,桶采用链式队列结构 */
{      int i, j, k, power = 1;
       LQueue *tub;
